use clap::Parser;
use regex::RegexBuilder;
use std::fs;
use std::io::{self, Read};
use std::path::PathBuf;

#[derive(Parser)]
#[command(name = "executable", version = "sd v1.0.0", about = "An intuitive find & replace CLI")]
struct Args {
    /// The regexp or string (if using `-F`) to search for
    #[arg(value_name = "FIND")]
    find: String,

    /// What to replace each match with. Unless in string mode, you may use captured values like $1, $2, etc
    #[arg(value_name = "REPLACE_WITH")]
    replace_with: String,

    /// The path to file(s). This is optional - sd can also read from STDIN.
    /// Note: sd modifies files in-place by default. See documentation for examples.
    #[arg(value_name = "FILES")]
    files: Vec<PathBuf>,

    /// Display changes in a human reviewable format
    #[arg(short, long)]
    preview: bool,

    /// Treat FIND and REPLACE_WITH args as literal strings
    #[arg(short = 'F', long)]
    fixed_strings: bool,

    /// Limit the number of replacements that can occur per file. 0 indicates unlimited replacements
    #[arg(short = 'n', long, default_value = "0")]
    max_replacements: usize,

    /// Regex flags. May be combined (like `-f mc`).
    /// c - case-sensitive
    /// e - disable multi-line matching
    /// i - case-insensitive
    /// m - multi-line matching
    /// s - make `.` match newlines
    /// w - match full words only
    #[arg(short = 'f', long)]
    flags: Option<String>,
}

fn main() {
    let args = Args::parse();

    // Determine input
    let input = if args.files.is_empty() {
        // Read from stdin
        let mut buffer = String::new();
        io::stdin()
            .read_to_string(&mut buffer)
            .expect("Failed to read from stdin");
        buffer
    } else {
        // Process files
        for file_path in &args.files {
            if let Err(e) = process_file(&args, file_path) {
                eprintln!("Error processing file {}: {}", file_path.display(), e);
            }
        }
        return;
    };

    // Process stdin
    let result = perform_replace(&args, &input).expect("Replace operation failed");
    print!("{}", result);
}

fn process_file(args: &Args, file_path: &PathBuf) -> io::Result<()> {
    let original_content = fs::read_to_string(file_path)?;
    let replaced_content = perform_replace(args, &original_content)
        .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    if args.preview {
        // Show original and replacement
        println!("{}", replaced_content);
        println!("{}", original_content);
    } else {
        // Write modified file
        fs::write(file_path, replaced_content)?;
    }

    Ok(())
}

fn perform_replace(args: &Args, input: &str) -> Result<String, String> {
    if args.fixed_strings {
        // String literal mode - no regex
        Ok(perform_literal_replace(input, &args.find, &args.replace_with, args.max_replacements))
    } else {
        // Regex mode
        perform_regex_replace(input, &args.find, &args.replace_with, &args.flags, args.max_replacements)
    }
}

fn perform_literal_replace(input: &str, find: &str, replace_with: &str, max_replacements: usize) -> String {
    let mut result = String::new();
    let mut remaining = input;
    let mut count = 0;

    loop {
        if max_replacements > 0 && count >= max_replacements {
            result.push_str(remaining);
            break;
        }

        match remaining.find(find) {
            Some(pos) => {
                result.push_str(&remaining[..pos]);
                result.push_str(replace_with);
                remaining = &remaining[pos + find.len()..];
                count += 1;
            }
            None => {
                result.push_str(remaining);
                break;
            }
        }
    }

    result
}

fn perform_regex_replace(
    input: &str,
    pattern: &str,
    replacement: &str,
    flags: &Option<String>,
    max_replacements: usize,
) -> Result<String, String> {
    let mut builder = RegexBuilder::new(pattern);

    let flag_str = flags.as_deref().unwrap_or("");

    let case_sensitive = flag_str.contains('c');
    let disable_multiline = flag_str.contains('e');
    let case_insensitive = flag_str.contains('i');
    let multiline = flag_str.contains('m');
    let dotall = flag_str.contains('s');
    let word_boundary = flag_str.contains('w');

    // Handle case sensitivity (case-sensitive flag wins if both provided)
    if case_insensitive && !case_sensitive {
        builder.case_insensitive(true);
    }

    // Handle multi-line flag (m enables multiline, e disables it)
    if !disable_multiline && multiline {
        builder.multi_line(true);
    }

    // Dotall - make . match newlines
    if dotall {
        builder.dot_matches_new_line(true);
    }

    let pattern_to_use = if word_boundary {
        format!(r"\b{}\b", pattern)
    } else {
        pattern.to_string()
    };

    let regex = builder.build(&pattern_to_use).map_err(|e| e.to_string())?;

    let mut result = String::new();
    let mut last_end = 0;
    let mut count = 0;

    for cap in regex.captures_iter(input) {
        if max_replacements > 0 && count >= max_replacements {
            break;
        }

        let matched = cap.get(0).unwrap();
        result.push_str(&input[last_end..matched.start()]);

        let replaced = replace_with_captures(replacement, &cap);
        result.push_str(&replaced);

        last_end = matched.end();
        count += 1;
    }

    result.push_str(&input[last_end..]);

    Ok(result)
}

fn replace_with_captures(replacement: &str, captures: &regex::Captures) -> String {
    let mut result = String::new();
    let mut chars = replacement.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch == '$' {
            if let Some(&next_ch) = chars.peek() {
                if next_ch == '$' {
                    // Escaped $
                    chars.next();
                    result.push('$');
                } else if next_ch == '{' {
                    // Named group with braces: ${name}
                    chars.next(); // consume '{'
                    let mut name = String::new();
                    while let Some(&c) = chars.peek() {
                        if c == '}' {
                            chars.next(); // consume '}'
                            break;
                        }
                        name.push(chars.next().unwrap());
                    }
                    if let Ok(captured) = captures.name(&name) {
                        result.push_str(captured.map(|m| m.as_str()).unwrap_or(""));
                    }
                } else if next_ch.is_ascii_digit() {
                    // Numbered group: $1, $2, etc or named without braces
                    let mut group_id = String::new();
                    while let Some(&c) = chars.peek() {
                        if c.is_ascii_digit() {
                            group_id.push(chars.next().unwrap());
                        } else if c.is_ascii_alphabetic() || c == '_' {
                            // Named group without braces: $name
                            while let Some(&c2) = chars.peek() {
                                if c2.is_ascii_alphanumeric() || c2 == '_' {
                                    group_id.push(chars.next().unwrap());
                                } else {
                                    break;
                                }
                            }
                            break;
                        } else {
                            break;
                        }
                    }

                    // Try as number first
                    if let Ok(index) = group_id.parse::<usize>() {
                        if let Some(captured) = captures.get(index) {
                            result.push_str(captured.as_str());
                        }
                    } else {
                        // Try as named group
                        if let Ok(captured) = captures.name(&group_id) {
                            result.push_str(captured.map(|m| m.as_str()).unwrap_or(""));
                        }
                    }
                } else {
                    // Just a $ followed by something not special
                    result.push('$');
                }
            } else {
                result.push('$');
            }
        } else {
            result.push(ch);
        }
    }

    result
}
