    )

    parser.add_argument(
        '-V', '--version',
        action='version',
        version='sd v1.0.0'
    )

    return parser.parse_args()

def process_literal_replace(text: str, find: str, replace_with: str, max_replacements: int) -> str:
    """Perform literal string replacement."""
    result = text
    count = 0
    while True:
        if max_replacements > 0 and count >= max_replacements:
            break
        idx = result.find(find)
        if idx == -1:
            break
        result = result[:idx] + replace_with + result[idx + len(find):]
        count += 1
    return result

def process_regex_replace(text: str, pattern: str, replacement: str, flags: str, max_replacements: int) -> str:
    """Perform regex replacement."""

    # Parse flags
    case_insensitive = 'i' in flags and 'c' not in flags
    multiline = 'm' in flags and 'e' not in flags
    dotall = 's' in flags
    word_boundary = 'w' in flags

    # Build regex flags
    regex_flags = 0
    if case_insensitive:
        regex_flags |= re.IGNORECASE
    if multiline:
        regex_flags |= re.MULTILINE
    if dotall:
        regex_flags |= re.DOTALL

    # Apply word boundary if needed
    if word_boundary:
        pattern = r'\b' + pattern + r'\b'

    try:
        regex = re.compile(pattern, regex_flags)
    except re.error as e:
        print(f"error: Invalid regex: {e}", file=sys.stderr)
        sys.exit(1)

    # Perform replacement with limit
    if max_replacements <= 0:
        return regex.sub(lambda m: replace_with_captures(replacement, m), text)
    else:
        result = text
        count = 0
        def replacer(m):
            nonlocal count
            if count < max_replacements:
                count += 1
                return replace_with_captures(replacement, m)
            else:
                return m.group(0)
        return regex.sub(replacer, text)

