    """Replace placeholders like $1, $2, $name with actual captured values."""
    result = []
    i = 0
    while i < len(replacement):
        if replacement[i] == '$':
            if i + 1 < len(replacement):
                if replacement[i + 1] == '$':
                    # Escaped dollar sign
                    result.append('$')
                    i += 2
                elif replacement[i + 1] == '{':
                    # Named group with braces: ${name}
                    i += 2
                    name = ''
                    while i < len(replacement) and replacement[i] != '}':
                        name += replacement[i]
                        i += 1
                    if i < len(replacement):
                        i += 1  # skip }
                    try:
                        result.append(match.group(name))
                    except (IndexError, AttributeError):
                        pass
                elif replacement[i + 1].isdigit() or replacement[i + 1].isalpha() or replacement[i + 1] == '_':
                    # Numbered or named group without braces
                    i += 1
                    group_id = ''
                    while i < len(replacement) and (replacement[i].isalnum() or replacement[i] == '_'):
                        group_id += replacement[i]
                        i += 1

                    # Try as number first
                    try:
                        idx = int(group_id)
                        result.append(match.group(idx))
                    except (ValueError, IndexError):
                        # Try as named group
                        try:
                            result.append(match.group(group_id))
                        except (IndexError, AttributeError):
                            pass
                else:
                    result.append('$')
                    i += 1
            else:
                result.append('$')
                i += 1
        else:
            result.append(replacement[i])
            i += 1

    return ''.join(result)

def process_file(filepath: Path, find: str, replace_with: str, flags: str, max_replacements: int, 
                 fixed_strings: bool, preview: bool):
    """Process a single file."""
    try:
        with open(filepath, 'r') as f:
            original_content = f.read()
    except Exception as e:
        print(f"error: Failed to read file {filepath}: {e}", file=sys.stderr)
        return

    if fixed_strings:
        modified_content = process_literal_replace(original_content, find, replace_with, max_replacements)
    else:
        modified_content = process_regex_replace(original_content, find, replace_with, flags, max_replacements)

    if preview:
        # Show modified then original
        print(modified_content, end='')
        print(original_content, end='')
    else:
        # Write modified content back
        try:
            with open(filepath, 'w') as f:
                f.write(modified_content)
        except Exception as e:
            print(f"error: Failed to write file {filepath}: {e}", file=sys.stderr)

def main():
    args = parse_args()

    if args.files:
        # Process files
        for filepath in args.files:
            process_file(
                Path(filepath),
                args.find,
                args.replace_with,
                args.flags,
                args.max_replacements,
                args.fixed_strings,
                args.preview
            )
    else:
        # Read from stdin
        try:
            stdin_content = sys.stdin.read()
        except Exception as e:
            print(f"error: Failed to read from stdin: {e}", file=sys.stderr)
            sys.exit(1)

        if args.fixed_strings:
            result = process_literal_replace(stdin_content, args.find, args.replace_with, args.max_replacements)
        else:
            result = process_regex_replace(stdin_content, args.find, args.replace_with, args.flags, args.max_replacements)

        sys.stdout.write(result)

