	}

	// Adjust pattern for case insensitivity using Go regex
	if caseInsensitive {
		actualPattern = "(?i)" + actualPattern
	}

	// Compile regex
	re, err := regexp.Compile(actualPattern)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: Invalid regex: %v\n", err)
		os.Exit(1)
	}

