package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"strings"
)

func main() {
	// Define command-line flags
	previewFlag := flag.Bool("preview", false, "Display changes in a human reviewable format")
	shortPreview := flag.Bool("p", false, "Display changes in a human reviewable format")
	fixedStringsFlag := flag.Bool("fixed-strings", false, "Treat FIND and REPLACE_WITH args as literal strings")
	shortFixed := flag.Bool("F", false, "Treat FIND and REPLACE_WITH args as literal strings")
	maxReplacements := flag.Int("max-replacements", 0, "Limit the number of replacements that can occur per file")
	shortMaxReplacements := flag.Int("n", 0, "Limit the number of replacements that can occur per file")
	flagsStr := flag.String("flags", "", "Regex flags")
	shortFlags := flag.String("f", "", "Regex flags")

	// Custom usage message
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "sd v1.0.0\n")
		fmt.Fprintf(os.Stderr, "An intuitive find & replace CLI\n\n")
		fmt.Fprintf(os.Stderr, "Usage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n")
		fmt.Fprintf(os.Stderr, "Arguments:\n")
		fmt.Fprintf(os.Stderr, "  <FIND>\n")
		fmt.Fprintf(os.Stderr, "          The regexp or string (if using `-F`) to search for\n\n")
		fmt.Fprintf(os.Stderr, "  <REPLACE_WITH>\n")
		fmt.Fprintf(os.Stderr, "          What to replace each match with. Unless in string mode, you may use captured values like\n")
		fmt.Fprintf(os.Stderr, "          $1, $2, etc\n\n")
		fmt.Fprintf(os.Stderr, "  [FILES]...\n")
		fmt.Fprintf(os.Stderr, "          The path to file(s). This is optional - sd can also read from STDIN.\n")
		fmt.Fprintf(os.Stderr, "          Note: sd modifies files in-place by default. See documentation for examples.\n\n")
		fmt.Fprintf(os.Stderr, "Options:\n")
		fmt.Fprintf(os.Stderr, "  -p, --preview\n")
		fmt.Fprintf(os.Stderr, "          Display changes in a human reviewable format\n\n")
		fmt.Fprintf(os.Stderr, "  -F, --fixed-strings\n")
		fmt.Fprintf(os.Stderr, "          Treat FIND and REPLACE_WITH args as literal strings\n\n")
		fmt.Fprintf(os.Stderr, "  -n, --max-replacements <LIMIT>\n")
		fmt.Fprintf(os.Stderr, "          Limit the number of replacements that can occur per file. 0 indicates unlimited\n")
		fmt.Fprintf(os.Stderr, "          replacements\n\n")
		fmt.Fprintf(os.Stderr, "  -f, --flags <FLAGS>\n")
		fmt.Fprintf(os.Stderr, "          Regex flags. May be combined (like `-f mc`).\n")
		fmt.Fprintf(os.Stderr, "          c - case-sensitive\n")
		fmt.Fprintf(os.Stderr, "          e - disable multi-line matching\n")
		fmt.Fprintf(os.Stderr, "          i - case-insensitive\n")
		fmt.Fprintf(os.Stderr, "          m - multi-line matching\n")
		fmt.Fprintf(os.Stderr, "          s - make `.` match newlines\n")
		fmt.Fprintf(os.Stderr, "          w - match full words only\n\n")
		fmt.Fprintf(os.Stderr, "  -h, --help\n")
		fmt.Fprintf(os.Stderr, "          Print help (see a summary with '-h')\n\n")
		fmt.Fprintf(os.Stderr, "  -V, --version\n")
		fmt.Fprintf(os.Stderr, "          Print version\n")
	}

	flag.Parse()

	// Handle version and help
	for _, arg := range os.Args[1:] {
		if arg == "-V" || arg == "--version" {
			fmt.Println("sd v1.0.0")
			os.Exit(0)
		}
		if arg == "-h" || arg == "--help" {
			flag.Usage()
			os.Exit(0)
		}
	}

	args := flag.Args()
	if len(args) < 2 {
		fmt.Fprintf(os.Stderr, "error: missing required arguments\n")
		os.Exit(1)
	}

	find := args[0]
	replaceWith := args[1]
	var files []string
	if len(args) > 2 {
		files = args[2:]
	}

	// Consolidate flags
	preview := *previewFlag || *shortPreview
	fixedStrings := *fixedStringsFlag || *shortFixed
	maxRepl := *maxReplacements
	if *shortMaxReplacements != 0 {
		maxRepl = *shortMaxReplacements
	}
	flags := *flagsStr
	if *shortFlags != "" {
		flags = *shortFlags
	}

	if len(files) == 0 {
		// Read from stdin
		input, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: Failed to read from stdin: %v\n", err)
			os.Exit(1)
		}
		text := string(input)

		var result string
		if fixedStrings {
			result = performLiteralReplace(text, find, replaceWith, maxRepl)
		} else {
			result = performRegexReplace(text, find, replaceWith, flags, maxRepl)
		}

		fmt.Print(result)
	} else {
		// Process files
		for _, file := range files {
			processFile(file, find, replaceWith, flags, maxRepl, fixedStrings, preview)
		}
	}
}

func performLiteralReplace(input, find, replaceWith string, maxReplacements int) string {
	result := input
	count := 0
	for {
		if maxReplacements > 0 && count >= maxReplacements {
			break
		}
		idx := strings.Index(result, find)
		if idx == -1 {
			break
		}
		result = result[:idx] + replaceWith + result[idx+len(find):]
		count++
	}
	return result
}

func performRegexReplace(input, pattern, replacement, flags string, maxReplacements int) string {
	caseInsensitive := strings.Contains(flags, "i") && !strings.Contains(flags, "c")
	wordBoundary := strings.Contains(flags, "w")

	actualPattern := pattern
	if wordBoundary {
		actualPattern = `\b` + pattern + `\b`
	}

	// Adjust pattern for case insensitivity using Go regex
	if caseInsensitive {
		actualPattern = "(?i)" + actualPattern
	}

	// Compile regex
	re, err := regexp.Compile(actualPattern)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: Invalid regex: %v\n", err)
		os.Exit(1)
	}

