	names := re.SubexpNames()
	nameToIndex := make(map[string]int)
	for i, name := range names {
		if name != "" {
			nameToIndex[name] = i
		}
	}

	// Perform replacement
	if maxReplacements <= 0 {
		// Replace all
		matches := re.FindAllStringSubmatchIndex(input, -1)
		if matches == nil {
			return input
		}

		result := ""
		lastEnd := 0
		for _, match := range matches {
			start := match[0]
			end := match[1]
			result += input[lastEnd:start]
			result += replaceWithCaptures(replacement, input, match, nameToIndex)
			lastEnd = end
		}
		result += input[lastEnd:]
		return result
	} else {
		// Replace up to maxReplacements
		result := ""
		lastEnd := 0
		count := 0

		matches := re.FindAllStringSubmatchIndex(input, -1)
		if matches == nil {
			return input
		}

		for _, match := range matches {
			if count >= maxReplacements {
				break
			}
			start := match[0]
			end := match[1]
			result += input[lastEnd:start]
			result += replaceWithCaptures(replacement, input, match, nameToIndex)
			lastEnd = end
			count++
		}
		result += input[lastEnd:]
		return result
	}
}

func replaceWithCaptures(replacement, input string, match []int, nameToIndex map[string]int) string {
	result := ""
	i := 0
	for i < len(replacement) {
		if replacement[i] == '$' && i+1 < len(replacement) {
			if replacement[i+1] == '$' {
				result += "$"
				i += 2
			} else if replacement[i+1] == '{' {
				// Named group with braces: ${name}
				i += 2
				name := ""
				for i < len(replacement) && replacement[i] != '}' {
					name += string(replacement[i])
					i++
				}
				if i < len(replacement) {
					i++ // skip }
				}
				// Look up the group index
				if idx, ok := nameToIndex[name]; ok && idx*2+1 < len(match) {
					start := match[idx*2]
					end := match[idx*2+1]
					if start >= 0 && end >= 0 {
						result += input[start:end]
					}
				}
			} else if replacement[i+1] >= '0' && replacement[i+1] <= '9' {
				i++
				numStr := ""
				for i < len(replacement) && replacement[i] >= '0' && replacement[i] <= '9' {
					numStr += string(replacement[i])
					i++
				}

				groupNum := 0
				for _, c := range numStr {
					groupNum = groupNum*10 + int(c-'0')
				}
				groupNum *= 2 // Convert to match array index

				if groupNum >= 0 && groupNum+1 < len(match) {
					start := match[groupNum]
					end := match[groupNum+1]
					if start >= 0 && end >= 0 {
						result += input[start:end]
					}
				}
			} else if (replacement[i+1] >= 'a' && replacement[i+1] <= 'z') ||
				(replacement[i+1] >= 'A' && replacement[i+1] <= 'Z') ||
				replacement[i+1] == '_' {
				// Named group without braces: $name
				i++
				name := ""
				for i < len(replacement) && ((replacement[i] >= 'a' && replacement[i] <= 'z') ||
					(replacement[i] >= 'A' && replacement[i] <= 'Z') ||
					(replacement[i] >= '0' && replacement[i] <= '9') ||
					replacement[i] == '_') {
					name += string(replacement[i])
					i++
				}
				// Look up the group index
				if idx, ok := nameToIndex[name]; ok && idx*2+1 < len(match) {
					start := match[idx*2]
					end := match[idx*2+1]
					if start >= 0 && end >= 0 {
						result += input[start:end]
					}
				}
			} else {
				result += "$"
				i++
			}
		} else {
			result += string(replacement[i])
			i++
		}
	}
	return result
}

func processFile(filepath, find, replaceWith, flags string, maxReplacements int, fixedStrings, preview bool) {
	content, err := os.ReadFile(filepath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: Failed to read file %s: %v\n", filepath, err)
		return
	}

	text := string(content)
	var modified string
	if fixedStrings {
		modified = performLiteralReplace(text, find, replaceWith, maxReplacements)
	} else {
		modified = performRegexReplace(text, find, replaceWith, flags, maxReplacements)
	}

	if preview {
		fmt.Print(modified)
		fmt.Print(text)
	} else {
		err = os.WriteFile(filepath, []byte(modified), 0644)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: Failed to write file %s: %v\n", filepath, err)
		}
	}
}
