package main

import (
	"fmt"
	"io"
	"os"
	"regexp"
	"strings"
)

func main() {
	// Manual parsing to handle -- properly
	args := os.Args[1:]

	// Handle version and help early
	for _, arg := range args {
		if arg == "-V" || arg == "--version" {
			fmt.Println("sd v1.0.0")
			os.Exit(0)
		}
		if arg == "-h" || arg == "--help" {
			printHelp()
			os.Exit(0)
		}
	}

	// Parse arguments manually
	var find, replaceWith string
	var files []string
	var preview, fixedStrings bool
	var maxReplacements int
	var flags string

	i := 0
	doubleRashFound := false

	for i < len(args) {
		arg := args[i]

		if !doubleRashFound && arg == "--" {
			doubleRashFound = true
			i++
			continue
		}

		if !doubleRashFound && strings.HasPrefix(arg, "-") && arg != "-" {
			// Parse flag
			switch arg {
			case "-p", "--preview":
				preview = true
			case "-F", "--fixed-strings":
				fixedStrings = true
			case "-n", "--max-replacements":
				i++
				if i >= len(args) {
					fmt.Fprintf(os.Stderr, "error: -n/--max-replacements requires a value\n")
					os.Exit(1)
				}
				var err error
				maxReplacements, err = parseInt(args[i])
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: invalid value for -n/--max-replacements\n")
					os.Exit(1)
				}
			case "-f", "--flags":
				i++
				if i >= len(args) {
					fmt.Fprintf(os.Stderr, "error: -f/--flags requires a value\n")
					os.Exit(1)
				}
				flags = args[i]
			default:
				fmt.Fprintf(os.Stderr, "error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [OPTIONS] <find> <replace-with> [files]...\n\nFor more information try --help\n", arg)
				os.Exit(1)
			}
		} else {
			// Positional argument
			if find == "" {
				find = arg
			} else if replaceWith == "" {
				replaceWith = arg
			} else {
				files = append(files, arg)
			}
		}

		i++
	}

	if find == "" || replaceWith == "" {
		fmt.Fprintf(os.Stderr, "error: missing required arguments\n")
		os.Exit(1)
	}

	if len(files) == 0 {
		// Read from stdin
		input, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: Failed to read from stdin: %v\n", err)
			os.Exit(1)
		}
		text := string(input)

		var result string
		if fixedStrings {
			result = performLiteralReplace(text, find, replaceWith, maxReplacements)
		} else {
			result = performRegexReplace(text, find, replaceWith, flags, maxReplacements)
		}

		fmt.Print(result)
	} else {
		// Process files
		for _, file := range files {
			processFile(file, find, replaceWith, flags, maxReplacements, fixedStrings, preview)
		}
	}
}

func parseInt(s string) (int, error) {
	result := 0
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, fmt.Errorf("invalid number")
		}
		result = result*10 + int(c-'0')
	}
	return result, nil
}

func printHelp() {
	fmt.Fprintf(os.Stderr, "sd v1.0.0\n")
	fmt.Fprintf(os.Stderr, "An intuitive find & replace CLI\n\n")
	fmt.Fprintf(os.Stderr, "Usage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n")
	fmt.Fprintf(os.Stderr, "Arguments:\n")
	fmt.Fprintf(os.Stderr, "  <FIND>\n")
	fmt.Fprintf(os.Stderr, "          The regexp or string (if using `-F`) to search for\n\n")
	fmt.Fprintf(os.Stderr, "  <REPLACE_WITH>\n")
