	fmt.Fprintf(os.Stderr, "          $1, $2, etc\n\n")
	fmt.Fprintf(os.Stderr, "  [FILES]...\n")
	fmt.Fprintf(os.Stderr, "          The path to file(s). This is optional - sd can also read from STDIN.\n")
	fmt.Fprintf(os.Stderr, "          Note: sd modifies files in-place by default. See documentation for examples.\n\n")
	fmt.Fprintf(os.Stderr, "Options:\n")
	fmt.Fprintf(os.Stderr, "  -p, --preview\n")
	fmt.Fprintf(os.Stderr, "          Display changes in a human reviewable format\n\n")
	fmt.Fprintf(os.Stderr, "  -F, --fixed-strings\n")
	fmt.Fprintf(os.Stderr, "          Treat FIND and REPLACE_WITH args as literal strings\n\n")
	fmt.Fprintf(os.Stderr, "  -n, --max-replacements <LIMIT>\n")
	fmt.Fprintf(os.Stderr, "          Limit the number of replacements that can occur per file. 0 indicates unlimited\n")
	fmt.Fprintf(os.Stderr, "          replacements\n\n")
	fmt.Fprintf(os.Stderr, "  -f, --flags <FLAGS>\n")
	fmt.Fprintf(os.Stderr, "          Regex flags. May be combined (like `-f mc`).\n")
	fmt.Fprintf(os.Stderr, "          c - case-sensitive\n")
	fmt.Fprintf(os.Stderr, "          e - disable multi-line matching\n")
	fmt.Fprintf(os.Stderr, "          i - case-insensitive\n")
	fmt.Fprintf(os.Stderr, "          m - multi-line matching\n")
	fmt.Fprintf(os.Stderr, "          s - make `.` match newlines\n")
	fmt.Fprintf(os.Stderr, "          w - match full words only\n\n")
	fmt.Fprintf(os.Stderr, "  -h, --help\n")
	fmt.Fprintf(os.Stderr, "          Print help (see a summary with '-h')\n\n")
	fmt.Fprintf(os.Stderr, "  -V, --version\n")
	fmt.Fprintf(os.Stderr, "          Print version\n")
}

func performLiteralReplace(input, find, replaceWith string, maxReplacements int) string {
	result := input
	count := 0
	for {
		if maxReplacements > 0 && count >= maxReplacements {
			break
		}
		idx := strings.Index(result, find)
		if idx == -1 {
			break
		}
		result = result[:idx] + replaceWith + result[idx+len(find):]
		count++
	}
	return result
}

func performRegexReplace(input, pattern, replacement, flags string, maxReplacements int) string {
	caseInsensitive := strings.Contains(flags, "i") && !strings.Contains(flags, "c")
	multiline := strings.Contains(flags, "m") && !strings.Contains(flags, "e")
	dotall := strings.Contains(flags, "s")
	wordBoundary := strings.Contains(flags, "w")

	actualPattern := pattern

	// Build prefix with flags
	var prefix string
	if dotall {
		prefix += "(?s)"
	}
	if multiline {
		prefix += "(?m)"
	}
	if caseInsensitive {
		prefix += "(?i)"
	}

	if wordBoundary {
		actualPattern = `\b` + pattern + `\b`
	}

	actualPattern = prefix + actualPattern

	// Compile regex
	re, err := regexp.Compile(actualPattern)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: Invalid regex: %v\n", err)
		os.Exit(1)
	}

	// Build a map of group names to indices
	names := re.SubexpNames()
	nameToIndex := make(map[string]int)
	for i, name := range names {
		if name != "" {
			nameToIndex[name] = i
		}
	}

	// Perform replacement
	if maxReplacements <= 0 {
		// Replace all
		matches := re.FindAllStringSubmatchIndex(input, -1)
		if matches == nil {
			return input
		}

		result := ""
		lastEnd := 0
		for _, match := range matches {
			start := match[0]
			end := match[1]
			result += input[lastEnd:start]
			result += replaceWithCaptures(replacement, input, match, nameToIndex)
			lastEnd = end
		}
		result += input[lastEnd:]
		return result
	} else {
		// Replace up to maxReplacements
		result := ""
		lastEnd := 0
		count := 0

		matches := re.FindAllStringSubmatchIndex(input, -1)
		if matches == nil {
			return input
		}

		for _, match := range matches {
			if count >= maxReplacements {
				break
			}
			start := match[0]
			end := match[1]
			result += input[lastEnd:start]
			result += replaceWithCaptures(replacement, input, match, nameToIndex)
			lastEnd = end
			count++
		}
		result += input[lastEnd:]
		return result
	}
}

func replaceWithCaptures(replacement, input string, match []int, nameToIndex map[string]int) string {
	result := ""
	i := 0
	for i < len(replacement) {
		if replacement[i] == '$' && i+1 < len(replacement) {
			if replacement[i+1] == '$' {
				result += "$"
				i += 2
			} else if replacement[i+1] == '{' {
				// Named group with braces: ${name}
				i += 2
				name := ""
				for i < len(replacement) && replacement[i] != '}' {
					name += string(replacement[i])
					i++
				}
				if i < len(replacement) {
					i++ // skip }
				}
				// Look up the group index
				if idx, ok := nameToIndex[name]; ok && idx*2+1 < len(match) {
					start := match[idx*2]
					end := match[idx*2+1]
					if start >= 0 && end >= 0 {
						result += input[start:end]
					}
				}
			} else if replacement[i+1] >= '0' && replacement[i+1] <= '9' {
				i++
				numStr := ""
				for i < len(replacement) && replacement[i] >= '0' && replacement[i] <= '9' {
					numStr += string(replacement[i])
					i++
				}

				groupNum := 0
				for _, c := range numStr {
					groupNum = groupNum*10 + int(c-'0')
				}
				groupNum *= 2 // Convert to match array index

				if groupNum >= 0 && groupNum+1 < len(match) {
					start := match[groupNum]
					end := match[groupNum+1]
					if start >= 0 && end >= 0 {
						result += input[start:end]
					}
				}
			} else if (replacement[i+1] >= 'a' && replacement[i+1] <= 'z') ||
				(replacement[i+1] >= 'A' && replacement[i+1] <= 'Z') ||
				replacement[i+1] == '_' {
				// Named group without braces: $name
				i++
				name := ""
				for i < len(replacement) && ((replacement[i] >= 'a' && replacement[i] <= 'z') ||
					(replacement[i] >= 'A' && replacement[i] <= 'Z') ||
					(replacement[i] >= '0' && replacement[i] <= '9') ||
					replacement[i] == '_') {
					name += string(replacement[i])
					i++
				}
				// Look up the group index
				if idx, ok := nameToIndex[name]; ok && idx*2+1 < len(match) {
					start := match[idx*2]
					end := match[idx*2+1]
					if start >= 0 && end >= 0 {
						result += input[start:end]
					}
				}
			} else {
				result += "$"
				i++
			}
		} else {
			result += string(replacement[i])
			i++
		}
	}
	return result
}

func processFile(filepath, find, replaceWith, flags string, maxReplacements int, fixedStrings, preview bool) {
	content, err := os.ReadFile(filepath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: Failed to read file %s: %v\n", filepath, err)
		return
	}

	text := string(content)
	var modified string
	if fixedStrings {
		modified = performLiteralReplace(text, find, replaceWith, maxReplacements)
	} else {
		modified = performRegexReplace(text, find, replaceWith, flags, maxReplacements)
	}

	if preview {
		fmt.Print(modified)
		fmt.Print(text)
	} else {
		err = os.WriteFile(filepath, []byte(modified), 0644)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: Failed to write file %s: %v\n", filepath, err)
		}
	}
}
