	dotall := strings.Contains(flags, "s")
	wordBoundary := strings.Contains(flags, "w")

	actualPattern := pattern

	// Build prefix with flags
	var prefix string
	if dotall {
		prefix += "(?s)"
	}
	if multiline {
		prefix += "(?m)"
	}
	if caseInsensitive {
		prefix += "(?i)"
	}

	if wordBoundary {
		actualPattern = `\b` + pattern + `\b`
	}

	actualPattern = prefix + actualPattern

	// Compile regex
	re, err := regexp.Compile(actualPattern)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: Invalid regex: %v\n", err)
		os.Exit(1)
	}

	// Build a map of group names to indices
	names := re.SubexpNames()
	nameToIndex := make(map[string]int)
	for i, name := range names {
		if name != "" {
			nameToIndex[name] = i
		}
