				i += 2
			} else if replacement[i+1] == '{' {
				// Named group with braces: ${name}
				i += 2
				name := ""
				for i < len(replacement) && replacement[i] != '}' {
					name += string(replacement[i])
					i++
				}
				if i < len(replacement) {
