func performLiteralReplace(input, find, replaceWith string, maxReplacements int) string {
	result := input
	count := 0
	for {
		if maxReplacements > 0 && count >= maxReplacements {
			break
		}
		idx := strings.Index(result, find)
		if idx == -1 {
			break
		}
		result = result[:idx] + replaceWith + result[idx+len(find):]
		count++
	}
	return result
}

func performRegexReplace(input, pattern, replacement, flags string, maxReplacements int) string {
	// Determine which flags to use
	// If both 'i' and 'c' are present, check what the last one is
	// Actually, looking at documentation, if 'c' is present, use case-sensitive (no (?i))
	// Otherwise, if 'i' is present, use case-insensitive

	hasCaseSensitive := strings.Contains(flags, "c")
	hasCaseInsensitive := strings.Contains(flags, "i")

	var caseInsensitive bool
	if hasCaseSensitive && hasCaseInsensitive {
		// If both are present, they override each other
		// Let's see: the order in flags string matters
		lastCaseIdx := strings.LastIndex(flags, "c")
		lastInsensitiveIdx := strings.LastIndex(flags, "i")
		caseInsensitive = lastInsensitiveIdx > lastCaseIdx
	} else if hasCaseInsensitive {
		caseInsensitive = true
	}

	multiline := strings.Contains(flags, "m") && !strings.Contains(flags, "e")
	dotall := strings.Contains(flags, "s")
	wordBoundary := strings.Contains(flags, "w")

	actualPattern := pattern

	// Build prefix with flags
	var prefix string
	if dotall {
		prefix += "(?s)"
	}
	if multiline {
		prefix += "(?m)"
	}
	if caseInsensitive {
		prefix += "(?i)"
	}

	if wordBoundary {
		actualPattern = `\b` + pattern + `\b`
	}

	actualPattern = prefix + actualPattern

	// Compile regex
	re, err := regexp.Compile(actualPattern)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: Invalid regex: %v\n", err)
		os.Exit(1)
	}

	// Build a map of group names to indices
	names := re.SubexpNames()
	nameToIndex := make(map[string]int)
	for i, name := range names {
		if name != "" {
			nameToIndex[name] = i
		}
	}

	// Perform replacement
	if maxReplacements <= 0 {
		// Replace all
		matches := re.FindAllStringSubmatchIndex(input, -1)
		if matches == nil {
			return input
		}

		result := ""
		lastEnd := 0
		for _, match := range matches {
			start := match[0]
			end := match[1]
			result += input[lastEnd:start]
			result += replaceWithCaptures(replacement, input, match, nameToIndex)
			lastEnd = end
		}
		result += input[lastEnd:]
		return result
	} else {
		// Replace up to maxReplacements
		result := ""
		lastEnd := 0
		count := 0

		matches := re.FindAllStringSubmatchIndex(input, -1)
		if matches == nil {
			return input
		}

		for _, match := range matches {
			if count >= maxReplacements {
				break
			}
			start := match[0]
			end := match[1]
			result += input[lastEnd:start]
			result += replaceWithCaptures(replacement, input, match, nameToIndex)
			lastEnd = end
			count++
		}
		result += input[lastEnd:]
		return result
	}
}

func replaceWithCaptures(replacement, input string, match []int, nameToIndex map[string]int) string {
	result := ""
	i := 0
	for i < len(replacement) {
